SELECT *
FROM ${tableName}
WHERE parent_id = #{parentId}
ORDER BY sort_order ASC, id ASC

SELECT *
FROM ${tableName}
WHERE level = #{level}
ORDER BY sort_order ASC, id ASC

SELECT *
FROM ${tableName}
ORDER BY path ASC, sort_order ASC

SELECT *
FROM ${tableName}
WHERE id IN

    #{id}

ORDER BY path ASC, sort_order ASC

WITH RECURSIVE tree_cte AS (
    SELECT *
    FROM ${tableName}
    WHERE id = #{rootId}
    UNION ALL
    SELECT t.*
    FROM ${tableName} t
    INNER JOIN tree_cte tc ON t.parent_id = tc.id
)
SELECT * FROM tree_cte
WHERE id != #{rootId}
ORDER BY path ASC, sort_order ASC

WITH RECURSIVE tree_cte AS (
    SELECT id, parent_id
    FROM ${tableName}
    WHERE id = #{rootId}
    UNION ALL
    SELECT t.id, t.parent_id
    FROM ${tableName} t
    INNER JOIN tree_cte tc ON t.parent_id = tc.id
)
SELECT COUNT(*) - 1 FROM tree_cte

